function x(t,e){if(Number.isNaN(t.getTime()))return"-";let i=t.getDay(),g=c(t),l=Math.floor((t.getMonth()+3)/3).toString();const n={"Y+":t.getFullYear().toString(),"m+":(t.getMonth()+1).toString(),"d+":t.getDate().toString(),"H+":t.getHours().toString(),"M+":t.getMinutes().toString(),"S+":t.getSeconds().toString(),"q+":l},r={0:"日",1:"一",2:"二",3:"三",4:"四",5:"五",6:"六"},p={1:"一",2:"二",3:"三",4:"四"};/(W+)/.test(e)&&(e=e.replace(RegExp.$1,RegExp.$1.length>1?RegExp.$1.length>2?"星期"+r[i]:"周"+r[i]:r[i])),/(Q+)/.test(e)&&(e=e.replace(RegExp.$1,RegExp.$1.length==4?"第"+p[l]+"季度":p[l])),/(Z+)/.test(e)&&(e=e.replace(RegExp.$1,RegExp.$1.length==3?"第"+g+"周":g+""));for(let u in n){let s=new RegExp("("+u+")").exec(e);s&&(e=e.replace(s[1],RegExp.$1.length==1?n[u]:n[u].padStart(RegExp.$1.length,"0")))}return e}function c(t){let e=new Date(t.getTime()),i=e.getDay()||7;e.setDate(e.getDate()-i+1+5);let g=new Date(e.getFullYear(),0,1),l=g.getDay(),n=1;l!=0&&(n=7-l+1),g=new Date(e.getFullYear(),0,1+n);let r=Math.ceil((e.valueOf()-g.valueOf())/864e5);return Math.ceil(r/7)}export{x as f};
